import type { IconManifest } from '../../domain/fileIcons';
import manifest from './manifest.generated.json';

/**
 * The Material Icon Theme lookup table, generated by `scripts/material-icons.mjs`
 * from the `material-icon-theme` package (MIT).
 */
export const materialManifest: IconManifest = manifest;

/** Where the app serves an icon from; the script copies the files into `public/material-icons/`. */
export function iconUrl(name: string): string {
  return `/material-icons/${name}.svg`;
}
